const base = (prompt: L, context: L, hint: L, success: L): TaskBase => ({ prompt, context, hint, success,
  correction: l('Compare your submitted work with the supplied rule. Record the first different state or calculation, then revise that step.', 'अपने दिए काम को बताए नियम से मिलाएँ। सबसे पहली अलग स्थिति या गणना लिखें, फिर वही कदम सुधारें।'),
});
const choice = (prompt: L, context: L, correct: string, rows: [string, L, L][]): ChoiceTask => ({
  ...base(prompt, context, l('Check the precondition and the result of each proposed action.', 'हर प्रस्ताव की पूर्वशर्त और परिणाम जाँचें।'), l('Your choice follows the stated rule and has a reproducible reason.', 'आपका चुनाव दिए नियम पर चलता है और उसका कारण दोहराकर जाँचा जा सकता है।')),
  kind: 'choice', correct, options: rows.map(([id,label,feedback]) => ({id,label,feedback})),
});
const story = (rows: [L,L,L][]) => rows.map(([title,caption,dialogue])=>({title,caption,dialogue}));
const node = (id: string, label: L, x: number, y: number, value?: L): VisualNode => ({id,label,x,y,value,shape:'card'});
const edge = (id: string, from: string, to: string, label?: L): VisualEdge => ({id,from,to,label});
const frame = (label: L, description: L, id: string, x: number, y: number, value: L, options: Partial<VisualStep> = {}): VisualStep => ({label,description,active:[id],moves:[{id,x,y}],...options,values:{[id]:value,...options.values}});
const vs = (...steps: [VisualStep,VisualStep,VisualStep]): VisualScene => ({steps});
const explore = (title:L,prompt:L, rows:[string,L,number,number][]): ChapterVisual['exploration'] => ({title,prompt,variants:rows.map(([id,label,scene,step])=>({id,label,scene,step}))});

