// Frames override the base diagram independently. Seed the prior accepted work explicitly,
// so a later frame never depends on values or positions retained by an earlier scene.
const seedState = (chapter:Class10Chapter, scene:number, step:number, values:Record<string,L>, moves:VisualStep['moves']=[]) => {
  const target=chapter.visual.scenes[scene].steps[step];
  target.values={...target.values,...values};
  target.moves=[...(target.moves??[]).filter(move=>!moves.some(other=>other.id===move.id)),...moves];
};
seedState(dictionaries,2,2,{or:l('6','6')});
for (const step of [0,1,2]) seedState(dictionaries,3,step,{or:l('6','6')});
seedState(dictionaries,4,0,{or:l('6','6')});
seedState(dictionaries,4,1,{or:l('6','6'),nx:l('5','5')});
seedState(dictionaries,4,2,{or:l('6','6'),nx:l('5','5')});
seedState(dictionaries,5,0,{or:l('6','6'),bk:l('3','3'),nx:l('5','5')});
for (const step of [1,2]) seedState(sorting,1,step,{counts:l('comparisons=1; swaps=1','तुलना=1; बदलाव=1')});
for (const step of [0,1]) seedState(sorting,3,step,{counts:l('comparisons=1; swaps=1','तुलना=1; बदलाव=1')});
for (const step of [0,1,2]) seedState(sorting,4,step,{counts:l('comparisons=2; swaps=1','तुलना=2; बदलाव=1')});
seedState(sorting,5,0,{counts:l('comparisons=2; swaps=1','तुलना=2; बदलाव=1')});
seedState(methods,2,1,{a:l('4 before doubling','दोगुने से पहले 4'),b:l('16 before doubling','दोगुने से पहले 16')});
for (const step of [0,1,2]) seedState(methods,3,step,{input:l('n: 4 → 8','आकार n: 4 → 8')});
seedState(methods,3,1,{b:l('16 before doubling','दोगुने से पहले 16')});
seedState(methods,3,2,{a:l('4 → 8','गिनती 4 → 8')});
seedState(methods,5,1,{input:l('n=6; budget 30','n=6; सीमा 30')});
for (const step of [0,1]) seedState(routes,2,step,{tally:l('1 valid move; cost 1','1 मान्य चाल; खर्च 1')});
seedState(routes,3,0,{tally:l('2 moves; cost 3','2 चालें; खर्च 3')});
